#!/usr/bin/env bash
# Transporter subsystem -- Patcher 3 of 3: the UI.
# Adds templates/transporter.html (rider page: register, accept, pickup, confirm)
# and a "Request a transporter" action on the seller's order (shows the pickup
# code). Frontend only: no migration. Hard-refresh afterwards.
set -uo pipefail
if [ ! -f templates/digital_store.html ] || [ ! -f manage.py ]; then
  echo "X Run from the Django project root."; exit 1
fi
BK="transportui_backup_$(date +%Y%m%d-%H%M%S)"; mkdir -p "$BK"
cp -a templates/digital_store.html "$BK/digital_store.html"
HAD_RIDER=0; [ -f templates/transporter.html ] && { HAD_RIDER=1; cp -a templates/transporter.html "$BK/transporter.html"; }
echo ">> Backup: $BK/"
cat > .tui.py << 'TUIW_EOF'
import sys, os, ast, base64

TRANSP_HTML_B64 = ""

DS_INJECT = r'''        function tjOverlay(html){
            var ov=document.createElement('div');
            ov.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;z-index:99999;padding:1rem';
            var box=document.createElement('div');
            box.style.cssText='background:#fff;border-radius:14px;max-width:400px;width:100%;padding:1.1rem 1.2rem;box-shadow:0 10px 40px rgba(0,0,0,.25)';
            box.innerHTML=html; ov.appendChild(box); document.body.appendChild(ov);
            ov.onclick=function(e){ if(e.target===ov){ try{document.body.removeChild(ov);}catch(x){} } };
            return { ov: ov, box: box, close: function(){ try{document.body.removeChild(ov);}catch(x){} } };
        }
        window.requestTransporter = async function(orderId){
            var existing=null;
            try{
                var r=await fetch(API_BASE+'/delivery-jobs/',{headers:{'Authorization':'Bearer '+(token||'')}});
                if(r.ok){ var d=await r.json(); var list=Array.isArray(d)?d:((d&&d.results)||[]); existing=list.find(function(j){return Number(j.order)===Number(orderId);})||null; }
            }catch(e){}
            if(existing){ tjShowJob(existing); return; }
            tjShowCreate(orderId);
        };
        function tjShowCreate(orderId){
            var html=''
                +'<div style="font-weight:800;font-size:1.05rem;margin-bottom:.2rem">Request a transporter</div>'
                +'<div style="font-size:.8rem;color:#6b7280;margin-bottom:.7rem">A registered rider will pick up and deliver. You will get a pickup code to read to them at hand-over.</div>'
                +'<label style="font-size:.75rem;font-weight:600;color:#374151">Pickup location</label><input id="tj_pick" placeholder="Where the rider collects" style="width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:.45rem;margin:.15rem 0 .5rem;font-size:.85rem">'
                +'<label style="font-size:.75rem;font-weight:600;color:#374151">Drop location</label><input id="tj_drop" placeholder="Where it is delivered" style="width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:.45rem;margin:.15rem 0 .5rem;font-size:.85rem">'
                +'<label style="font-size:.75rem;font-weight:600;color:#374151">Vehicle</label><select id="tj_veh" style="width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:.45rem;margin:.15rem 0 .5rem;font-size:.85rem"><option value="">Any</option><option value="boda">Boda boda</option><option value="pickup">Pickup</option><option value="truck">Truck</option><option value="taxi">Taxi / van</option><option value="bicycle">Bicycle</option></select>'
                +'<label style="font-size:.75rem;font-weight:600;color:#374151">Offered fee (UGX, optional)</label><input id="tj_fee" type="number" min="0" placeholder="e.g. 5000" style="width:100%;box-sizing:border-box;border:1px solid #d1d5db;border-radius:8px;padding:.45rem;margin:.15rem 0 .8rem;font-size:.85rem">'
                +'<div style="display:flex;gap:.5rem;justify-content:flex-end"><button id="tj_cancel" type="button" style="padding:.45rem .8rem;border:1px solid #d1d5db;background:#fff;border-radius:8px;font-size:.82rem;font-weight:600;cursor:pointer">Cancel</button><button id="tj_ok" type="button" style="padding:.45rem .9rem;border:none;background:#10b981;color:#fff;border-radius:8px;font-size:.82rem;font-weight:700;cursor:pointer">Request</button></div>';
            var m=tjOverlay(html);
            m.box.querySelector('#tj_cancel').onclick=m.close;
            m.box.querySelector('#tj_ok').onclick=async function(){
                var payload={ order: orderId, pickup_location: m.box.querySelector('#tj_pick').value.trim(), drop_location: m.box.querySelector('#tj_drop').value.trim(), vehicle_type_required: m.box.querySelector('#tj_veh').value, offered_fee: Number(m.box.querySelector('#tj_fee').value||0) };
                try{
                    var r=await fetch(API_BASE+'/delivery-jobs/',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+(token||'')},body:JSON.stringify(payload)});
                    var j=null; try{ j=await r.json(); }catch(e){}
                    if(!r.ok){ throw new Error((j&&(j.detail||j.order||j.non_field_errors))||'Could not create the request.'); }
                    m.close(); tjShowJob(j);
                }catch(e){ toast(e.message||'Could not create the request.','error'); }
            };
        }
        function tjShowJob(job){
            var code=job.pickup_code ? String(job.pickup_code) : null;
            var html=''
                +'<div style="font-weight:800;font-size:1.05rem;margin-bottom:.2rem">Transporter request</div>'
                +'<div style="font-size:.8rem;color:#6b7280;margin-bottom:.7rem">Status: <b>'+(job.status||'open')+'</b></div>';
            if(code){
                html+='<div style="padding:.7rem .9rem;background:#ecfdf5;border:1px solid #a7f3d0;border-radius:10px;text-align:center">'
                    +'<div style="font-size:.72rem;font-weight:700;color:#065f46;text-transform:uppercase;letter-spacing:.05em">Pickup code</div>'
                    +'<div style="font-size:1.8rem;font-weight:900;letter-spacing:.2em;color:#047857;font-family:Georgia,serif">'+code+'</div>'
                    +'<div style="font-size:.72rem;color:#6b7280;margin-top:.2rem">Read this to the rider at pickup. Do not share it before they collect the goods.</div>'
                    +'</div>';
            } else {
                html+='<div style="font-size:.82rem;color:#6b7280">No rider assigned yet, or pickup is already complete.</div>';
            }
            html+='<div style="display:flex;gap:.5rem;justify-content:flex-end;margin-top:.9rem">';
            if(job.status==='open'||job.status==='accepted'){
                html+='<button id="tj_cancel_job" type="button" style="padding:.45rem .8rem;border:1px solid #fca5a5;background:#fff;color:#dc2626;border-radius:8px;font-size:.82rem;font-weight:600;cursor:pointer">Cancel request</button>';
            }
            html+='<button id="tj_done" type="button" style="padding:.45rem .9rem;border:none;background:#10b981;color:#fff;border-radius:8px;font-size:.82rem;font-weight:700;cursor:pointer">Done</button></div>';
            var m=tjOverlay(html);
            m.box.querySelector('#tj_done').onclick=m.close;
            var cb=m.box.querySelector('#tj_cancel_job');
            if(cb){ cb.onclick=async function(){
                try{ await fetch(API_BASE+'/delivery-jobs/'+job.id+'/cancel/',{method:'POST',headers:{'Authorization':'Bearer '+(token||'')}}); toast('Request cancelled.','success'); m.close(); MKT.loaded=false; loadOrders(); }
                catch(e){ toast('Could not cancel.','error'); }
            }; }
        }
        function sellerEscrowBlock(o){'''

def run(ds_path, html_path, html_content):
    # 1) create the rider page if missing
    if html_content:
        if not os.path.exists(html_path):
            open(html_path,'w',encoding='utf-8').write(html_content)
            print('   OK created', html_path)
        else:
            print('   - exists, left as-is:', html_path)

    # 2) digital_store.html: add Request-a-transporter button + inject modal fns
    d=open(ds_path,encoding='utf-8').read()
    if 'requestTransporter' not in d:
        B_OLD = "            if (es === 'held' && !esc.otp_issued_at)\n                return '<div class=\"mt-2\"><button onclick=\"dispatchOrder(' + esc.id + ')\" class=\"px-3 py-1.5 text-xs font-semibold bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition\"><i class=\"fas fa-truck\"></i> Dispatch order</button></div>';"
        B_NEW = ("            if (es === 'held' && !esc.otp_issued_at)\n"
                 "                return '<div class=\"mt-2 flex flex-wrap gap-2\">'\n"
                 "                    + '<button onclick=\"dispatchOrder(' + esc.id + ')\" class=\"px-3 py-1.5 text-xs font-semibold bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition\"><i class=\"fas fa-truck\"></i> Dispatch myself</button>'\n"
                 "                    + '<button onclick=\"requestTransporter(' + o.id + ')\" class=\"px-3 py-1.5 text-xs font-semibold bg-white text-emerald-700 border border-emerald-200 rounded-lg hover:bg-emerald-50 transition\"><i class=\"fas fa-motorcycle\"></i> Request a transporter</button>'\n"
                 "                    + '</div>';")
        if B_OLD not in d:
            print('   X sellerEscrowBlock held-branch anchor not found'); sys.exit(1)
        d=d.replace(B_OLD,B_NEW,1)
        if 'function sellerEscrowBlock(o){' not in d:
            print('   X sellerEscrowBlock fn anchor not found'); sys.exit(1)
        d=d.replace('        function sellerEscrowBlock(o){', DS_INJECT, 1)
        open(ds_path,'w',encoding='utf-8').write(d)
        print('   OK digital_store.html: Request-a-transporter + pickup-code modal')
    else:
        print('   - digital_store.html already has transporter request')
    print('DONE')

if __name__ == '__main__':
    html = base64.b64decode(TRANSP_HTML_B64).decode('utf-8')
    run('templates/digital_store.html', 'templates/transporter.html', html)
TUIW_EOF
python3 .tui.py; RC=$?
rm -f .tui.py
if [ $RC -ne 0 ]; then
  echo "X failed; restoring."
  cp -a "$BK/digital_store.html" templates/digital_store.html
  if [ "$HAD_RIDER" -eq 1 ]; then cp -a "$BK/transporter.html" templates/transporter.html; else rm -f templates/transporter.html; fi
  exit 1
fi
echo ""
echo ">> Applied. Hard-refresh digital_store.html. Riders use:  http://127.0.0.1:8000/transporter.html"
echo ">> Rollback: cp -a $BK/digital_store.html templates/digital_store.html$([ "$HAD_RIDER" -eq 1 ] && echo " && cp -a $BK/transporter.html templates/transporter.html" || echo " && rm -f templates/transporter.html")"
